//! What the editor reads of opentide's models, generated by
//! `opentide-schema` in this process (UC-2.6, #926), never read from a file
//! a workspace or a host supplies:
//!
//! - the configuration schemas hover and completion walk in a file under
//!   `.opentide/configurations/` ([`configuration_schemas`]), the documents
//!   `opentide generate schemas` writes for them (UC-1.8b);
//! - each root's Tide field and deprecation catalogs ([`FieldCatalog`]),
//!   which hover, completion and highlighting read: what `opentide generate
//!   schemas` writes to `.opentide/lsp/catalogs/generated/`, built from the
//!   models and the root's resolved configuration, and handed to the engine
//!   (`opentide_analysis::install_catalog`).

use opentide_analysis::{Catalog, ConfigurationSchemas};
use opentide_schema::generate::catalog::{deprecations_catalog, dump, fields_catalog};
use opentide_schema::generate::schema::Sources;
use opentide_schema::node::Node;
use opentide_schema::vocab::Vocabularies;
use opentide_workspace::{Configuration, Workspace};
use std::sync::{Arc, OnceLock};

/// The configuration schemas `opentide-schema` generates, built once per
/// process.
pub(crate) fn configuration_schemas() -> &'static ConfigurationSchemas {
    static SCHEMAS: OnceLock<ConfigurationSchemas> = OnceLock::new();
    SCHEMAS.get_or_init(|| {
        use opentide_schema::generate::configuration::{
            ROUTER_NAME, configuration_router, configuration_schemas,
        };
        let documents = configuration_schemas()
            .into_iter()
            .filter(|(name, _)| name != ROUTER_NAME);
        // The router is generated with a `files` table: this never fails.
        ConfigurationSchemas::new(&configuration_router(), documents).unwrap_or_default()
    })
}

/// The resolved configuration a field catalog is generated from. The
/// catalog's rows also draw on the object vocabularies, but no row the
/// models generate reads them (a test holds it), so the catalogs are
/// generated without them, as the engine's bundled ones are: an object added
/// or renamed never generates them again.
fn sources(config: &Node) -> Sources {
    let mut vocabularies = Vocabularies::bundled();
    for vocabulary in opentide_workspace::vocabularies::object_vocabularies(
        &opentide_workspace::Index::default(),
        config,
    ) {
        vocabularies.insert(vocabulary);
    }
    Sources {
        config: Arc::new(config.clone()),
        vocabularies: Arc::new(vocabularies),
    }
}

/// The bundled configuration, resolved: what a workspace with no
/// configuration of its own resolves to.
fn bundled_configuration() -> &'static Node {
    static BUNDLED: OnceLock<Node> = OnceLock::new();
    BUNDLED.get_or_init(|| {
        use opentide_schema::configuration::resolve::{Instance, resolve};
        resolve(&Instance {
            skip_parent: true,
            ..Instance::default()
        })
        .map(|resolved| resolved.tree)
        // The bundled configuration resolves (its tests say so); without it,
        // the catalogs are generated from no configuration at all.
        .unwrap_or_else(|_| Node::null_at(opentide_schema::node::Mark::default()))
    })
}

static DEFAULT: OnceLock<Arc<Catalog>> = OnceLock::new();

/// The catalogs for the bundled configuration, generated once per process
/// (a warm-up thread does it at start-up): what the documents outside every
/// root use, and a root whose configuration is the bundled one.
#[cfg_attr(
    target_family = "wasm",
    allow(
        dead_code,
        reason = "the WebAssembly builds have no warm-up thread to generate it"
    )
)]
pub(crate) fn default_catalog() -> Arc<Catalog> {
    Arc::clone(DEFAULT.get_or_init(|| Arc::new(build(&sources(bundled_configuration())))))
}

/// [`default_catalog`] if it has been generated, without waiting for it:
/// until then the engine keeps the catalogs compiled into it, which the same
/// models generated (a test holds it). A host with no warm-up thread (the
/// WebAssembly builds) keeps those, rather than generate the same catalogs
/// on a request.
pub(crate) fn default_catalog_if_ready() -> Option<Arc<Catalog>> {
    DEFAULT.get().cloned()
}

/// A root's Tide field and deprecation catalogs, generated from the models
/// for its configuration, again only when the configuration changes, and on
/// a thread of their own where there are threads, so no request waits for
/// them: until they are ready the root uses the ones it had.
#[derive(Default)]
pub(crate) struct FieldCatalog {
    /// The configuration the catalogs were generated for, and them.
    built: Option<(Arc<Configuration>, Arc<Catalog>)>,
    /// Catalogs being generated for a configuration.
    #[cfg(not(any(target_family = "wasm", fuzzing)))]
    building: Option<(Arc<Configuration>, std::thread::JoinHandle<Arc<Catalog>>)>,
}

/// Whether two configurations generate the same catalogs: the same
/// resolution, or equal trees.
fn same(a: &Arc<Configuration>, b: &Arc<Configuration>) -> bool {
    Arc::ptr_eq(a, b) || a.resolved.tree == b.resolved.tree
}

impl FieldCatalog {
    /// The catalogs for `workspace`: those generated for its configuration,
    /// or, while they are being generated, the ones generated before (none
    /// at first).
    pub(crate) fn for_workspace(&mut self, workspace: &Workspace) -> Option<Arc<Catalog>> {
        let config = workspace.configuration();
        #[cfg(not(any(target_family = "wasm", fuzzing)))]
        if self
            .building
            .as_ref()
            .is_some_and(|(_, handle)| handle.is_finished())
        {
            if let Some((for_config, handle)) = self.building.take() {
                if let Ok(catalog) = handle.join() {
                    self.built = Some((for_config, catalog));
                }
            }
        }
        if let Some((for_config, catalog)) = &self.built {
            if same(for_config, config) {
                return Some(Arc::clone(catalog));
            }
        }
        // The bundled configuration's are generated at start-up.
        if config.resolved.tree == *bundled_configuration() {
            let catalog = default_catalog_if_ready()?;
            self.built = Some((Arc::clone(config), Arc::clone(&catalog)));
            return Some(catalog);
        }
        let previous = self.built.as_ref().map(|(_, catalog)| Arc::clone(catalog));
        #[cfg(not(any(target_family = "wasm", fuzzing)))]
        {
            if self
                .building
                .as_ref()
                .is_some_and(|(for_config, _)| same(for_config, config))
            {
                return previous;
            }
            let tree = config.resolved.tree.clone();
            let spawned = std::thread::Builder::new()
                .name("opentide-lsp-catalog".to_owned())
                .spawn(move || Arc::new(build(&sources(&tree))));
            if let Ok(handle) = spawned {
                self.building = Some((Arc::clone(config), handle));
                return previous;
            }
        }
        let catalog = Arc::new(build(&sources(&config.resolved.tree)));
        self.built = Some((Arc::clone(config), Arc::clone(&catalog)));
        Some(catalog)
    }
}

/// The catalogs `opentide generate schemas` writes for `sources`, labelled
/// with this engine's version.
fn build(sources: &Sources) -> Catalog {
    Catalog {
        fields: Some(dump(&fields_catalog(crate::VERSION, sources))),
        deprecations: Some(dump(&deprecations_catalog(crate::VERSION))),
        // visibility.toml is installed on its own, so edits apply live.
        visibility: None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_configuration_schemas_route_every_file_the_router_names() {
        let schemas = configuration_schemas();
        let path = "/w/.opentide/configurations/sharing.toml";
        let text = "[[misp]]\nmax_tlp = ";
        let labels: Vec<String> =
            opentide_analysis::configuration_completions(schemas, path, text, text.len())
                .into_iter()
                .map(|item| item.label)
                .collect();
        assert!(
            labels.contains(&"\"amber+strict\"".to_owned()),
            "{labels:?}"
        );
    }

    /// The catalogs are generated without the object vocabularies
    /// ([`sources`]): no row reads them. If one comes to, this fails, and
    /// a root's objects must then be what its catalogs are generated from.
    #[test]
    fn no_catalog_row_reads_the_object_vocabularies() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../testdata/workspaces/tide_corpus");
        let workspace = Workspace::open(
            Arc::new(opentide_workspace::OsFs),
            opentide_workspace::Options {
                roots: opentide_workspace::RootOptions {
                    repo: Some(dir.clone()),
                    cwd: dir,
                    ..opentide_workspace::RootOptions::default()
                },
            },
        )
        .expect("the corpus opens");
        let config = &workspace.configuration().resolved.tree;
        let objects =
            opentide_workspace::vocabularies::object_vocabularies(workspace.index(), config);
        assert!(objects.iter().all(|v| !v.entries.is_empty()), "{objects:?}");
        let mut with_objects = sources(config);
        let mut vocabularies = (*with_objects.vocabularies).clone();
        for vocabulary in objects {
            vocabularies.insert(vocabulary);
        }
        with_objects.vocabularies = Arc::new(vocabularies);
        assert_eq!(build(&with_objects).fields, build(&sources(config)).fields);
    }

    /// The catalogs generated for the bundled configuration are the ones
    /// compiled into the engine, but for their version label.
    #[test]
    fn the_default_catalogs_are_the_bundled_ones() {
        let unlabelled = |text: &str| {
            let mut value: serde_json::Value = serde_json::from_str(text).expect("JSON");
            if let Some(object) = value.as_object_mut() {
                for key in opentide_schema::generate::catalog::LABEL_KEYS {
                    object.remove(key);
                }
            }
            value
        };
        let generated = default_catalog();
        let bundled = opentide_analysis::bundled_catalog();
        for (ours, theirs) in [
            (&generated.fields, &bundled.fields),
            (&generated.deprecations, &bundled.deprecations),
        ] {
            assert_eq!(
                unlabelled(ours.as_deref().expect("generated")),
                unlabelled(theirs.as_deref().expect("bundled"))
            );
        }
    }
}
